-- Cenários da IA: situações recorrentes com orientação de como agir, exemplo e desfecho esperado.
-- A IA consulta os cenários publicados pela ferramenta consultar_cenarios; cada cenário também roda como teste no Sandbox.
CREATE FUNCTION ai_norm(text) RETURNS text IMMUTABLE STRICT LANGUAGE sql AS $$SELECT lower(translate($1,'áàâãäéèêëíìîïóòôõöúùûüçÁÀÂÃÄÉÈÊËÍÌÎÏÓÒÔÕÖÚÙÛÜÇ','aaaaaeeeeiiiiooooouuuucAAAAAEEEEIIIIOOOOOUUUUC'))$$;
CREATE TABLE ai_scenarios(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),
 title text NOT NULL CHECK(length(title) BETWEEN 3 AND 120),
 situation text NOT NULL CHECK(length(situation) BETWEEN 10 AND 1000),
 guidance text NOT NULL CHECK(length(guidance) BETWEEN 10 AND 3000),
 example text NOT NULL DEFAULT '' CHECK(length(example)<=2000),
 avoid text NOT NULL DEFAULT '' CHECK(length(avoid)<=1000),
 test_message text NOT NULL DEFAULT '' CHECK(length(test_message)<=1000),
 expected_action text CHECK(expected_action IN('ASK_USER','ANSWER','HANDOFF')),
 expected_destination text CHECK(expected_destination IN('AI','recepcao','agenda','convenios','clinica','auditoria','financeiro')),
 tags text[] NOT NULL DEFAULT '{}',agent_specialties text[] NOT NULL DEFAULT '{}',
 status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN('DRAFT','PUBLISHED','ARCHIVED')),
 version int NOT NULL DEFAULT 1,created_by uuid REFERENCES users(id),updated_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(tenant_id,id));
CREATE INDEX ai_scenarios_tenant ON ai_scenarios(tenant_id,status);
CREATE TABLE ai_scenario_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),scenario_id uuid NOT NULL REFERENCES ai_scenarios(id),version int NOT NULL,snapshot jsonb NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(scenario_id,version));
CREATE TABLE ai_scenario_runs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),scenario_id uuid NOT NULL REFERENCES ai_scenarios(id),version int NOT NULL,conversation_id uuid REFERENCES conversations(id),agent_run_id uuid REFERENCES agent_runs(id),
 status text NOT NULL DEFAULT 'RUNNING' CHECK(status IN('RUNNING','PASSED','FAILED','ERROR')),checks jsonb NOT NULL DEFAULT '[]',reply text,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),finished_at timestamptz);
CREATE INDEX ai_scenario_runs_scenario ON ai_scenario_runs(scenario_id,created_at DESC);
-- Cenários só valem para agentes com a chave ligada; começa pela triagem.
ALTER TABLE agents ADD COLUMN use_scenarios boolean NOT NULL DEFAULT false;
UPDATE agents SET use_scenarios=true WHERE specialty='triagem';
-- O texto inicial de conhecimento dizia que nenhum provedor de IA estava conectado; isso confunde o modelo.
UPDATE agents SET knowledge='Use somente informações cadastradas e confirmadas pela clínica (profissionais, convênios, agenda e catálogo de serviços), consultadas pelas ferramentas. Regras de convênio cadastradas precisam de conferência contratual antes de serem prometidas à família.' WHERE knowledge LIKE 'Conhecimento inicial demonstrativo%';
INSERT INTO ai_scenarios(tenant_id,title,situation,guidance,example,avoid,test_message,expected_action,expected_destination,tags,status)
SELECT t.id,s.title,s.situation,s.guidance,s.example,s.avoid,s.test_message,s.expected_action,s.expected_destination,s.tags,'PUBLISHED' FROM tenants t CROSS JOIN (VALUES
 ('Família manda só uma saudação','A primeira mensagem é apenas "oi", "bom dia" ou uma apresentação, sem dizer o que precisa.','1) Cumprimente de volta pelo período do dia. 2) Pergunte em uma frase como pode ajudar. 3) Não consulte paciente, convênio nem profissionais ainda.','Família: Oi, bom dia!\nIA: Bom dia! Aqui é da Integrar. Como posso ajudar?','Não cite nomes de pacientes vinculados. Não ofereça lista de serviços sem a família pedir.','Oi, bom dia!','ASK_USER','AI',ARRAY['saudação','oi','bom dia','início']),
 ('Pedido médico ou laudo sem idade informada','A família conta que tem pedido médico ou laudo para terapias, mas ainda não disse a idade da criança nem o convênio.','1) Agradeça e diga que vai organizar o atendimento. 2) Pergunte idade e convênio (ou particular) numa única mensagem. 3) Se houver documento anexado, leia antes de perguntar. 4) Só monte o plano quando souber a idade.','Família: Tenho um pedido de fono e TO para meu filho.\nIA: Que bom que nos procurou! Para organizar, me diga a idade dele e se o atendimento será pelo convênio ou particular?','Não busque profissionais nem cite nomes antes de saber a idade. Não faça mais de duas perguntas.','Tenho um pedido médico de fono e terapia ocupacional para meu filho. Vocês atendem?','ASK_USER','AI',ARRAY['laudo','pedido médico','encaminhamento','idade','terapias']),
 ('Serviço que a clínica não oferece','A família pede um serviço fora do catálogo da clínica, como equoterapia, consulta médica, neurologista ou exame.','1) Consulte o catálogo de serviços para confirmar. 2) Diga com gentileza que a clínica não oferece aquele serviço. 3) Ofereça ajuda com os serviços que a clínica tem, se fizer sentido. 4) Registre no resumo para a equipe.','Família: Vocês fazem equoterapia?\nIA: Esse atendimento não é feito aqui na clínica. Se precisar de fono, TO, psicologia ou outras terapias, posso te ajudar a organizar.','Não indique outra clínica pelo nome. Não prometa que o serviço vai existir.','Vocês fazem equoterapia? A neuro pediu para minha filha.',NULL,'AI',ARRAY['não oferecido','equoterapia','neurologista','consulta médica','exame']),
 ('Família pede para falar com uma pessoa','A família pede expressamente um atendente humano, uma pessoa ou alguém da recepção.','1) Respeite o pedido sem insistir. 2) Avise em uma frase que vai chamar a equipe. 3) Encaminhe para a recepção com motivo USER_REQUEST e um resumo do que já foi dito.','Família: Quero falar com uma pessoa.\nIA: Claro! Vou chamar alguém da nossa equipe para continuar com você.','Não tente resolver antes de transferir. Não pergunte o motivo do pedido.','Quero falar com uma pessoa, por favor.','HANDOFF','recepcao',ARRAY['atendente','humano','pessoa','recepção']),
 ('Troca de profissional','A criança já é atendida na clínica e a família quer trocar de profissional por insatisfação, horário ou afinidade.','1) Acolha sem julgar o profissional atual. 2) Se a família ainda não disse, pergunte o motivo em uma frase, sem insistir. 3) Diga que a coordenação clínica vai avaliar a troca. 4) Encaminhe para a fila clinica com motivo OPERATIONAL_ACTION.','Família: Queria trocar a fono do meu filho.\nIA: Entendo. Vou passar seu pedido para a coordenação clínica, que avalia a troca e retorna com você.','Não critique nem defenda o profissional atual. Não prometa outro nome nem horário.','Meu filho já faz fono aí com a Dra. Kátia, mas eu queria trocar de profissional.','HANDOFF','clinica',ARRAY['troca','trocar profissional','insatisfação','mudar de terapeuta']),
 ('Reclamação sobre atendimento','A família reclama de cancelamento, atraso, cobrança, comunicação ou de algo que aconteceu na clínica.','1) Peça desculpas pelo transtorno em uma frase. 2) Não discuta a versão da família. 3) Diga que a equipe vai verificar o que aconteceu e retornar. 4) Encaminhe para a recepção com motivo OPERATIONAL_ACTION e o relato no resumo.','Família: Cancelaram a sessão em cima da hora!\nIA: Sinto muito pelo transtorno. Vou levar isso agora para a nossa equipe verificar e te dar um retorno.','Não justifique o problema, não culpe profissionais e não prometa compensação.','Estou muito chateada, a sessão de ontem foi cancelada em cima da hora e ninguém me avisou.','HANDOFF','recepcao',ARRAY['reclamação','cancelamento','atraso','insatisfação','cobrança']),
 ('Dúvida clínica ou sobre a terapia','A família pergunta sobre sintomas, evolução, efeitos da terapia, se deve parar, aumentar ou mudar algo no tratamento.','1) Acolha a preocupação. 2) Diga que essa orientação precisa ser dada por um profissional da clínica. 3) Encaminhe para a fila clinica com motivo CLINICAL_REVIEW.','Família: Meu filho está chorando muito depois da terapia, é normal?\nIA: Entendo sua preocupação. Vou passar para a coordenação clínica, que vai te orientar com segurança.','Não dê opinião clínica, não diga que é normal e não recomende parar ou continuar.','Meu filho começou a ter crises de choro depois da terapia, é normal? Devo parar?','HANDOFF','clinica',ARRAY['dúvida clínica','sintoma','evolução','terapia','parar tratamento']),
 ('Pergunta se a clínica aceita um convênio','A família quer saber se a clínica atende pelo convênio dela.','1) Consulte as regras de convênio cadastradas. 2) Se o convênio estiver cadastrado, diga que a clínica trabalha com ele e que a equipe confere a cobertura do plano. 3) Se não estiver, diga que não consta no cadastro e ofereça o atendimento particular ou a verificação pela equipe.','Família: Vocês aceitam Bradesco?\nIA: Trabalhamos com Bradesco Saúde, sim. A equipe confere a cobertura do seu plano antes de agendar. Qual atendimento você procura?','Não garanta cobertura nem autorização. Não invente convênios.','Vocês aceitam Bradesco Saúde?',NULL,'AI',ARRAY['convênio','plano de saúde','cobertura','aceita']),
 ('Desmarcar ou remarcar sessão','A família pede para desmarcar, cancelar ou mudar o horário de uma sessão já agendada.','1) Confirme qual sessão (dia e terapia) se a família não disse. 2) Diga que a recepção vai registrar e, se for remarcar, propor novo horário. 3) Encaminhe para a fila agenda com motivo OPERATIONAL_ACTION.','Família: Preciso desmarcar a sessão de quinta.\nIA: Tudo bem, vou passar para a nossa agenda registrar o cancelamento e te confirmar.','Não diga que a sessão já foi cancelada ou remarcada: isso exige a equipe.','Preciso desmarcar a sessão de quinta-feira da minha filha.','HANDOFF','agenda',ARRAY['desmarcar','cancelar sessão','remarcar','falta','reagendar']),
 ('Relato de urgência ou risco','A família descreve uma situação de urgência: queda com batida na cabeça, vômitos, convulsão, falta de ar, risco à segurança ou ideação de autoagressão.','1) Oriente em uma frase a procurar atendimento de emergência agora (SAMU 192 ou pronto-socorro). 2) Diga que a equipe da clínica foi avisada. 3) Encaminhe para a fila clinica com motivo CLINICAL_REVIEW.','Família: Meu filho bateu a cabeça e está vomitando.\nIA: Procure atendimento de emergência agora: ligue 192 (SAMU) ou vá ao pronto-socorro mais próximo. Já avisei nossa equipe.','Não avalie a gravidade, não sugira esperar e não peça dados de cadastro antes da orientação de emergência.','Meu filho bateu a cabeça forte e está vomitando, o que eu faço?','HANDOFF','clinica',ARRAY['urgência','emergência','risco','vômito','convulsão','queda'])
) AS s(title,situation,guidance,example,avoid,test_message,expected_action,expected_destination,tags);
INSERT INTO ai_scenario_versions(tenant_id,scenario_id,version,snapshot) SELECT tenant_id,id,1,to_jsonb(s) FROM ai_scenarios s;
